// Renders the polished granite used for the headstone on the landing page. It's procedural:
// nothing is photographed or generated by a model, so it carries no third-party rights.
//
// Run with: npm install --no-save sharp && node scripts/render-granite.js
const path = require("path");
const sharp = require("sharp");

const SIZE = 1200;
const BASE = [38, 47, 42];

function random(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Soft clouding that wraps at the edges, so the stone doesn't look like flat paint
function clouds(cells, seed) {
  const rand = random(seed);
  const grid = new Float32Array(cells * cells).map(() => rand());
  const smooth = (t) => t * t * (3 - 2 * t);
  return (u, v) => {
    const gx = u * cells;
    const gy = v * cells;
    const x0 = Math.floor(gx);
    const y0 = Math.floor(gy);
    const fx = smooth(gx - x0);
    const fy = smooth(gy - y0);
    const at = (x, y) => grid[(y % cells) * cells + (x % cells)];
    const top = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * fx;
    const bottom = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * fx;
    return top + (bottom - top) * fy;
  };
}

(async () => {
  const large = clouds(6, 3);
  const medium = clouds(40, 5);
  const rand = random(9);
  const pixels = Buffer.alloc(SIZE * SIZE * 3);

  for (let y = 0; y < SIZE; y++) {
    for (let x = 0; x < SIZE; x++) {
      const u = x / SIZE;
      const v = y / SIZE;
      const cloud = (large(u, v) - 0.5) * 7 + (medium(u, v) - 0.5) * 7;
      const grain = (rand() - 0.5) * 8;
      // Crystals: mostly dark flecks, with a few bright ones that catch the light
      const fleck = rand();
      const crystal = fleck > 0.994 ? 46 : fleck > 0.975 ? 15 : fleck < 0.02 ? -12 : 0;
      for (let c = 0; c < 3; c++) {
        const value = BASE[c] + cloud + grain + crystal;
        pixels[(y * SIZE + x) * 3 + c] = Math.max(0, Math.min(255, Math.round(value)));
      }
    }
  }

  const info = await sharp(pixels, { raw: { width: SIZE, height: SIZE, channels: 3 } })
    .webp({ quality: 74, effort: 6 })
    .toFile(path.join(__dirname, "..", "public", "img", "granite.webp"));
  console.log("granite.webp", SIZE + "px", Math.round(info.size / 1024) + "KB");
})();
